// ReSharper disable once CheckNamespace
namespace Wpf.Ui.Controls;

/// <summary>
/// Represents the Fluent item container generated by <see cref="ListBox"/>.
/// </summary>
/// <remarks>
/// Double-click activation is coordinated by the owning <see cref="ListBox"/> so explicitly
/// supplied native item containers and generated Fluent containers share the same behavior.
/// </remarks>
public class ListBoxItem : System.Windows.Controls.ListBoxItem
{
    static ListBoxItem()
    {
        DefaultStyleKeyProperty.OverrideMetadata(
            typeof(ListBoxItem),
            new FrameworkPropertyMetadata(typeof(ListBoxItem))
        );
    }

    // This container currently adds no custom behavior of its own — it exists so the owning
    // ListBox can produce a Fluent-styled item container via GetContainerForItemOverride.
    // Keep the type around as an extension point; any item-level behavior specific to the
    // Fluent design can be added here without affecting consumers that supply native containers.
}
